import React, { useState, useEffect } from 'react';
import Modal from '../components/Modal';
import Calendar from '../components/Calendar';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span>
      <span style={{ color: '#f59e0b' }}>{'★'.repeat(Math.floor(v))}</span>
      <span style={{ color: 'var(--text2)', fontSize: '.8rem' }}> {v.toFixed(1)}</span>
    </span>
  );
}

export default function ProfModal({ prof, onClose }) {
  const { user } = useAuth();
  const [tab, setTab] = useState('profil');
  const [avis, setAvis] = useState([]);
  const [dispos, setDispos] = useState([]);

  const [step, setStep] = useState(null);
  const [selectedDispo, setSelectedDispo] = useState(null);
  const [modeChoisi, setModeChoisi] = useState(null);
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [reservationFaite, setReservationFaite] = useState(null);

  const profId = prof.prof_id || prof.id;
  const profMode = prof.mode_enseignement || 'presentiel';
  const profNom = prof.user_nom || prof.nom || 'Professeur';

  useEffect(() => {
    if (tab === 'avis') {
      api.get(`/api/avis/professeur/${profId}`)
        .then(r => setAvis(r.data))
        .catch(() => setAvis([]));
    }
    if (tab === 'calendrier' || step === 'choix_dispo') {
      api.get(`/api/professeurs/${profId}/disponibilites`)
        .then(r => setDispos(r.data ?? []))
        .catch(() => setDispos([]));
    }
  }, [tab, step, profId]);

  const formatDate = (str) =>
    str ? new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', {
      weekday: 'long', day: 'numeric', month: 'long'
    }) : '';

  const getModeInfo = (mode) => {
    if (mode === 'en_ligne')
      return { icon: '🌐', label: 'En ligne', color: '#38bdf8', bg: 'rgba(56,189,248,0.12)' };
    return { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)' };
  };

  const getTarif = () => {
    const mode = modeChoisi || (profMode !== 'les_deux' ? profMode : null);
    if (mode === 'en_ligne') return prof.tarif_en_ligne;
    if (mode === 'presentiel') return prof.tarif_presentiel;
    return null;
  };

  const disposDisponibles = dispos.filter(d => d.nb_inscrits < d.nb_max_etudiants);

  const handleReserver = async () => {
    if (!selectedDispo) return;
    const mode = profMode === 'les_deux' ? modeChoisi : profMode;
    if (!mode) return alert('Veuillez choisir un mode de cours');

    const modeEffectif = selectedDispo.mode_seance !== 'les_deux'
      ? selectedDispo.mode_seance
      : mode;

    setSubmitting(true);
    try {
      const res = await api.post('/api/reservations/', {
        prof_id: profId,
        disponibilite_id: selectedDispo.id,
        date_cours: selectedDispo.date_specifique,
        heure_debut: selectedDispo.heure_debut,
        heure_fin: selectedDispo.heure_fin,
        mode_seance: modeEffectif,
        notes_etudiant: notes,
      });
      setReservationFaite(res.data);
      setStep('confirmation');
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSubmitting(false);
    }
  };

  /* ================= CONFIRMATION ================= */
  if (step === 'confirmation' && reservationFaite) {
    const mode = reservationFaite.mode_seance;
    const mi = getModeInfo(mode);

    return (
      <Modal onClose={onClose} maxWidth={500}>
        <div style={{ textAlign: 'center', padding: '10px 0 20px' }}>
          <div style={{ fontSize: '3rem' }}>🎉</div>
          <h2>Réservation envoyée !</h2>

          {/* CORRECTION ICI */}
          {mode === 'en_ligne' && reservationFaite.lien_meet && (
            <div style={{ marginTop: 20 }}>
              <div style={{ color: '#38bdf8', marginBottom: 10 }}>
                🌐 Lien Google Meet
              </div>

              <a
                href={reservationFaite.lien_meet}
                target="_blank"
                rel="noreferrer"
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 8,
                  background: '#38bdf8',
                  color: '#000',
                  padding: '10px',
                  borderRadius: 10,
                  textDecoration: 'none',
                  fontWeight: 'bold'
                }}
              >
                📹 Rejoindre le Meet
              </a>
            </div>
          )}

          <button onClick={onClose} style={{ marginTop: 20 }}>
            Fermer
          </button>
        </div>
      </Modal>
    );
  }

  /* ================= MAIN ================= */
  return (
    <Modal onClose={onClose} maxWidth={700}>
      <ModalHeader title="" onClose={onClose} />

      <div style={{ marginBottom: 20 }}>
        <h3>{profNom}</h3>
        <Stars n={prof.note_moyenne} />
      </div>

      <div style={{ display: 'flex', gap: 10 }}>
        <button onClick={() => setTab('profil')}>Profil</button>
        <button onClick={() => setTab('calendrier')}>Calendrier</button>
        <button onClick={() => setTab('avis')}>Avis</button>
      </div>

      {tab === 'profil' && (
        <div>
          <p>{prof.bio}</p>

          {user?.role === 'étudiant' && (
            <button onClick={() => setStep('choix_dispo')}>
              Réserver
            </button>
          )}
        </div>
      )}

      {step === 'choix_dispo' && (
        <div>
          {disposDisponibles.map(d => (
            <div key={d.id} onClick={() => setSelectedDispo(d)}>
              {formatDate(d.date_specifique)}
            </div>
          ))}

          {selectedDispo && (
            <button onClick={handleReserver}>
              Confirmer
            </button>
          )}
        </div>
      )}

      {tab === 'avis' && (
        <div>
          {avis.map(a => (
            <div key={a.id}>
              {a.etudiant} - {a.commentaire}
            </div>
          ))}
        </div>
      )}
    </Modal>
  );
}
